#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>

#include <poppler-global.h>
#include <poppler-document.h>
#include <poppler-page.h>
#include <poppler-page-renderer.h>

static void nop_func(const std::string& msg, void*) {};

int main(int argc, char *argv[]) {
  if (argc < 2) {
    fprintf(stderr, "Usage: %s <pdf_file>\n", argv[0]);
    return 1;
  }

  FILE *f = fopen(argv[1], "rb");
  if (!f) { perror("fopen"); return 1; }
  fseek(f, 0, SEEK_END);
  long sz = ftell(f);
  fseek(f, 0, SEEK_SET);
  uint8_t *buf = (uint8_t*)malloc(sz);
  fread(buf, 1, sz, f);
  fclose(f);

  poppler::set_debug_error_function(nop_func, nullptr);

  poppler::document *doc = poppler::document::load_from_raw_data((const char *)buf, sz);
  if (!doc || doc->is_locked()) {
    delete doc;
    free(buf);
    return 0;
  }

  poppler::page_renderer r;
  for (int i = 0; i < doc->pages(); i++) {
    poppler::page *p = doc->create_page(i);
    if (!p) {
      continue;
    }
    r.render_page(p);
    delete p;
  }

  delete doc;
  free(buf);
  return 0;
}
EOF
